steps.action:
curl -s -X POST "https://slack.com/api/conversations.list" -H "Authorization: Bearer <TOKEN>" -d "token=<TOKEN>&types=public_channel&limit=1000" | python3 -c "
import json,sys
data = json.load(sys.stdin)
if data.get('ok'):
    for c in data['channels']:
        if 'payments' in c['name']:
            print(c['id'], c['name'])
else:
    print('ERROR:', data)
"

curl -s -X POST "https://slack.com/api/search.messages" -H "Authorization: Bearer <TOKEN>" -d "token=<TOKEN>&query=Launch day! channel:payments-ops" | python3 -c "
import json,sys
data = json.load(sys.stdin)
if data.get('ok'):
    for m in data['messages']['matches']:
        print(m['ts'], m['user'], m['text'])
else:
    print('ERROR:', data)
"

curl -s -X POST "https://slack.com/api/conversations.history" -H "Authorization: Bearer <TOKEN>" -d "token=<TOKEN>&channel=C_OPS&limit=100" | python3 -c "
import json,sys
data = json.load(sys.stdin)
if data.get('ok'):
    for m in data['messages']:
        if m['type'] == 'message':
            print(m['ts'], m['user'], repr(m['text']))
else:
    print('ERROR:', data)
"
